/* Designed in em (1em = 16px = natural size 22 x 27.8 em), grows with the widget (aspect ratio kept),
   but never gets smaller than the natural size. .avr-box is the size container (see the Samsung remote). */

.avr-box {
   container-type: size;
   width: 100%;
   height: 100%;
   min-height: 446px;
   display: flex;
   align-items: center;
   justify-content: center;
}
.avr {
   --avr-key: #2c2d30;
   --avr-key-hi: #3a3b3f;
   --avr-lcd: #bfeaff;
   font-size: 16px;
   font-size: max(16px, min(calc(100cqw / 22), calc(100cqh / 27.8)));
   flex: none;
   width: 22em;
   height: 27.8em;
   padding: 0.9em;
   box-sizing: border-box;
   display: flex;
   flex-direction: column;
   gap: 0.7em;
   border-radius: 1.2em;
   background: linear-gradient(180deg, #34363a 0%, #1f2023 6%, #17181a 100%);
   box-shadow: inset 0 0.0625em 0 #ffffff14, 0 0.25em 0.875em #0008;
   color: #d8d8d8;
   user-select: none;
}
.avr button {
   border: 0;
   padding: 0;
   font: inherit;
   color: inherit;
   background: var(--avr-key);
   cursor: pointer;
   -webkit-tap-highlight-color: transparent;
}
.avr button:active {
   filter: brightness(1.6);
}
.avr .mdi {
   font-size: 1.3em;
   line-height: 1;
}
.avr-head {
   flex: none;
   height: 2.2em;
   display: flex;
   align-items: center;
   justify-content: space-between;
}
.avr-title {
   font-weight: bold;
   font-size: 1.05em;
   letter-spacing: 0.08em;
   opacity: 0.85;
}
.avr-power, .avr-z2power {
   width: 2.2em;
   height: 2.2em;
   border-radius: 50%;
}
.avr-power, .avr-z2power.off { color: #e53935; }
.avr.on .avr-power, .avr-z2power.on { color: #4caf50; box-shadow: 0 0 0.5em #4caf5066; }
.avr-display {
   flex: none;
   height: 4.2em;
   box-sizing: border-box;
   padding: 0.5em 0.8em;
   border-radius: 0.6em;
   background: #07090b;
   box-shadow: inset 0 0.0625em 0.25em #000, 0 0 0 0.0625em #ffffff10;
   display: grid;
   grid-template-columns: 1fr auto;
   align-items: center;
   gap: 0.5em;
   color: var(--avr-lcd);
   text-shadow: 0 0 0.4em #5fc8ff66;
}
.avr-lcd-left {
   min-width: 0;
   display: flex;
   flex-direction: column;
   gap: 0.15em;
}
.avr-source {
   font-size: 1.5em;
   line-height: 1.2;
   white-space: nowrap;
   overflow: hidden;
   text-overflow: ellipsis;
}
.avr-surround {
   font-size: 0.8em;
   opacity: 0.65;
   white-space: nowrap;
   overflow: hidden;
   text-overflow: ellipsis;
}
.avr-lcd-right {
   white-space: nowrap;
   text-align: right;
}
.avr-vol {
   font-size: 2em;
   line-height: 1;
}
.avr-unit {
   font-size: 0.8em;
   margin-left: 0.2em;
   opacity: 0.65;
}
.avr-mute {
   display: none;
   margin-right: 0.3em;
   color: #ff6b6b;
}
.avr-display.muted .avr-mute { display: inline; }
.avr-display.muted .avr-vol  { opacity: 0.4; }
.avr-vrow, .avr-z2vol {
   flex: none;
   height: 2.6em;
   display: flex;
   gap: 0.5em;
}
.avr-z2vol { height: 2em; }
.avr-vrow button, .avr-z2vol button {
   flex: 1;
   border-radius: 1.3em;
}
.avr-z2vol button { border-radius: 1em; }
.avr-mutebtn.muted { color: #e53935; }
.avr-srcs {
   flex: none;
   height: 4.8em;
   display: grid;
   grid-template-columns: repeat(4, 1fr);
   grid-template-rows: repeat(2, 2.2em);
   gap: 0.4em;
}
.avr-src {
   min-width: 0;
   padding: 0 0.3em !important;
   border-radius: 0.5em;
   font-size: 0.75em !important;
   white-space: nowrap;
   overflow: hidden;
   text-overflow: ellipsis;
}
.avr-src.aktiv {
   background: #1d4a63 !important;
   color: #fff;
   box-shadow: 0 0 0 0.15em #4fc3f7;
}
.avr-z2 {
   flex: none;
   height: 9.4em;
   display: flex;
   flex-direction: column;
   gap: 0.5em;
}
.avr-z2head {
   flex: none;
   height: 2.2em;
   display: flex;
   align-items: center;
   gap: 0.6em;
}
.avr-z2title {
   font-weight: bold;
   font-size: 0.9em;
   letter-spacing: 0.08em;
   opacity: 0.85;
}
.avr-z2info {
   flex: 1;
   min-width: 0;
   font-size: 0.75em;
   opacity: 0.8;
   white-space: nowrap;
   overflow: hidden;
   text-overflow: ellipsis;
}
.avr-z2power { width: 2em; height: 2em; }
.avr-z2srcs {
   height: 4.2em;
   grid-template-rows: repeat(2, 1.9em);
}
.avr-z2srcs .avr-src { font-size: 0.7em !important; }
